{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT CAST(time AS VARCHAR) t, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'attractions%' AND metric = 'container.memory.rss' ORDER BY time LIMIT 40", "claim": "Attractions pod RSS jumps from about 25 MB to about 772 MB around 07:26 and stays flat through the window."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name = 'attractions' GROUP BY 1", "claim": "No attractions spans at all in the abnormal window, versus 521 in the normal window."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY 1", "claim": "Frontend requests on the attraction paths /cinema, /museums and /restaurants all return errors (error share 1.0)."}
      ]
    },
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='user' GROUP BY 1", "claim": "The user deployment shows zero available replicas for the entire abnormal window; normal was 1."},
        {"kind": "metric", "sql": "SELECT CAST(min(time) AS VARCHAR) t0, CAST(max(time) AS VARCHAR) t1, min(value) mn, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name='user-544b8d4448-dmgn6' AND metric='k8s.container.ready' GROUP BY 1,2", "claim": "The user pod's container stays not ready from 07:25:55 to the end of the window."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE span_name='user.User/CheckUser' GROUP BY 1", "claim": "All 200 frontend calls to user.User/CheckUser fail with error status; no user server spans exist."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY 1,2,3", "claim": "Frontend HTTP attraction routes fail with 500s while attractions stops emitting spans."}
      ]
    },
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE span_name IN ('user.User/CheckUser','HTTP /user') GROUP BY 1,2", "claim": "Frontend's user.User/CheckUser calls and its HTTP /user requests all error out."},
        {"kind": "log", "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2", "claim": "Frontend logs 'User authentication failed' errors during the abnormal window."}
      ]
    }
  ]
}
